def is_auth(uid: int) -> bool:
    return bool(uid) and (uid == OWNER_ID or uid in SUDO_USERS)


def is_owner(uid: int) -> bool:
    return bool(uid) and uid == OWNER_ID


def is_main_bot(ctx: Any) -> bool:
    """Management / 'baap level' sirf hosting (main) bot pe."""
    try:
        bid = int(getattr(getattr(ctx, "bot", None), "id", 0) or 0)
    except Exception:
        bid = 0
    return not MAIN_BOT_ID or not bid or bid == MAIN_BOT_ID


def pool() -> list[Any]:
    return [b for b in ALL_BOTS if b is not None][:32]


def arg(update: Any) -> str:
    """Command ke baad ka text (PTB + plain object dono ke saath kaam kare)."""
    try:
        t = update.message.text or ""
    except Exception:
        t = getattr(update, "_text", "") or ""
    parts = t.split(None, 1)
    return parts[1].strip() if len(parts) > 1 else ""


def esc(value: Any) -> str:
    return _html.escape(str(value if value is not None else ""), quote=False)


def chat_id(update: Any) -> int:
    try:
        return int(update.effective_chat.id)
    except Exception:
        return int(getattr(update, "_cid", 0) or 0)


def is_private(update: Any) -> bool:
    try:
        return str(update.effective_chat.type) in ("private", "PRIVATE", "ChatType.PRIVATE")
    except Exception:
        return bool(getattr(update, "_private", False))


def uid_of(update: Any) -> int:
    try:
        return int(update.effective_user.id)
    except Exception:
        return int(getattr(update, "_uid", 0) or 0)


def now_ist() -> str:
    return datetime.now(_IST).strftime("%H:%M:%S")


def uptime_str() -> str:
    s = int(time.time() - START_TIME)
    d, r = divmod(s, 86400)
    h, r = divmod(r, 3600)
    m, sec = divmod(r, 60)
    return " ".join(f"{v}{u}" for v, u in ((d, "d"), (h, "h"), (m, "m"), (sec, "s")) if v) or "0s"


