def sc(t: Any) -> str:
    return str(t).translate(str.maketrans(_SC_MAP))


def sb(t: Any) -> str:
    return str(t).translate(_SANS_B)


def mono(t: Any) -> str:
    return str(t).translate(_MONO)


def fit(t: str, limit: int = 255) -> str:
    """Telegram title 255 chars; kabhi bhi broken surrogate na bhejein."""
    t = str(t)
    if len(t) <= limit:
        return t
    return t.encode("utf-8")[:limit].decode("utf-8", "ignore")


def u16(s: str) -> int:
    """Telegram entity offsets UTF-16 code units me hote hain."""
    return len(s.encode("utf-16-le")) // 2


