# ─── part 2 ────────────────────────────────────────────────────────────────


# ══════════════════════════════════════════════════════════════════════════
#   💎 PREMIUM ANIMATED EMOJI ENGINE
#   • 11 packs → 381 alt emoji → 1,924 document IDs (embedded, self-contained)
#   • ROTATION: ek hi "fix prefix emoji" ko har baar NAYI custom id milti hai —
#     pool khatam hone tak koi repeat nahi, phir naya cycle. Ultra premium feel.
#   • Bot API HTML  : <tg-emoji emoji-id="ID">ALT</tg-emoji>
#   • Bot API entity: MessageEntity(type="custom_emoji", offset, length, id)
#   • Telethon TL   : MessageEntityCustomEmoji / TextCustomEmoji(document_id)
#   • Hard fallback : premium na ho / server reject → plain Unicode emoji
#   Source: core.telegram.org/bots/api#formatting-options,
#           core.telegram.org/api/custom-emoji, Bot API changelog 2023-04-21
# ══════════════════════════════════════════════════════════════════════════

# EMOJI_IDS literal yahan injected hai (build time) — alts sorted by pool size.

_CE_CURSOR: dict[str, int] = {}
_CE_LAST: dict[str, str] = {}
_CE_ALL: list[str] = []
_CE_IDX = itertools.count()


def _load_extra_packs() -> None:
    """Attached packs ke alawa aur packs ho to runtime me jod do."""
    try:
        if not EXTRA_PACK_DIR.exists():
            return
        for f in sorted(EXTRA_PACK_DIR.glob("emojipack_*_data.txt")):
            try:
                d = ast.literal_eval(f.read_text(encoding="utf-8"))
                for e in d.get("emojis", []):
                    alt, cid = str(e.get("emoji", "")), str(e.get("custom_emoji_id", ""))
                    if not alt or not cid.isdigit():
                        continue
                    cur = tuple(EMOJI_IDS.get(alt, ()))
                    if cid not in cur:
                        EMOJI_IDS[alt] = cur + (cid,)
            except Exception:
                continue
    except Exception:
        pass


def ce_init() -> None:
    global _CE_ALL
    _load_extra_packs()
    _CE_ALL = [i for ids in EMOJI_IDS.values() for i in ids]
    log.info("emoji engine: %d alts / %d ids / premium=%s",
             len(EMOJI_IDS), len(_CE_ALL), PREMIUM_EMOJI)


def ce_id(alt: str) -> str:
    """ROTATING custom id — har call pe alag (jab tak pool khatam na ho)."""
    ids = EMOJI_IDS.get(alt)
    if not ids:
        return ""
    key = alt if len(ids) > 1 else ""
    if key:
        n = _CE_CURSOR.get(key, random.randrange(len(ids)))
        picked = ids[n % len(ids)]
        _CE_CURSOR[key] = (n + 1) % len(ids)
        if picked == _CE_LAST.get(key) and len(ids) > 1:
            picked = ids[(n + 1) % len(ids)]
            _CE_CURSOR[key] = (n + 2) % len(ids)
        _CE_LAST[key] = picked
        return picked
    return ids[0]


def ce(alt: str, fallback: str | None = None) -> str:
    """HTML-mode premium emoji. Premium OFF ya ID na ho → plain emoji."""
    fb = fallback if fallback is not None else alt
    if not PREMIUM_EMOJI:
        return fb
    cid = ce_id(alt)
    return f'<tg-emoji emoji-id="{cid}">{esc(fb)}</tg-emoji>' if cid else esc(fb)


def ce_plain(alt: str) -> str:
    return alt


def ce_tg_entity(alt: str, offset: int, length: int | None = None) -> MessageEntity | None:
    """Bot API entity object — UTF-16 offsets, exactly ONE regular emoji wrap."""
    if not PREMIUM_EMOJI or MessageEntity is None:
        return None
    cid = ce_id(alt)
    if not cid:
        return None
    try:
        return MessageEntity("custom_emoji", offset, length or u16(alt),
                             custom_emoji_id=cid)
    except Exception:
        return None


def ce_entities(text: str, budget: int = 90) -> list[MessageEntity]:
    """Poore text me jitne bhi pool-emoji ho, sab par custom entity laga do."""
    out: list[MessageEntity] = []
    if not PREMIUM_EMOJI:
        return out
    rx = re.compile("|".join(re.escape(k) for k in
                            sorted(EMOJI_IDS, key=len, reverse=True)))
    pos = prev = 0
    for m in rx.finditer(text):
        if len(out) >= budget:
            break
        pos += u16(text[prev:m.start()])
        e = ce_tg_entity(m.group(), pos, u16(m.group()))
        if e is not None:
            out.append(e)
        pos += u16(m.group())
        prev = m.end()
    return out


# ── fixed UI roles → har render me nayi custom id ────────────────────────────
ROLE_EMOJI: dict[str, str] = {
    "crown": "👑", "bolt": "⚡", "star": "🌟", "fire": "🔥", "gem": "💎",
    "heart": "❤️", "pink": "🩷", "white": "🤍", "skull": "💀", "ok": "✅",
    "no": "❌", "warn": "😈", "wait": "💤", "bot": "🐱", "globe": "🌎",
    "link": "🎀", "lock": "🔐", "key": "🎁", "rocket": "➡️", "shield": "✅",
    "sword": "😈", "moon": "🌙", "sun": "☁️", "flower": "🌸", "butter": "🦋",
    "cat": "🐱", "star2": "⭐", "spark": "✨", "black": "🖤", "note": "🎶",
}


def E(role: str) -> str:
    """Prefix/fixed emoji — har baar alag custom id, same Unicode fallback."""
    alt = ROLE_EMOJI.get(role, "✦")
    if not EMOJI_IDS.get(alt):                 # pack me na ho -> universal premium alt
        alt = "🌟"
    return ce(alt)


def pfx() -> str:
    """Command prefix ka premium emoji — har card/command pe NAYA id."""
    return ce("🌟")


def ce_strip(text: str) -> str:
    """<tg-emoji> tags hata kar plain text (notifications / fallback)."""
    return re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", text, flags=re.S)


def ce_count(text: str) -> int:
    return len(ce_tg_entities_pairs(text))


def ce_tg_entities_pairs(text: str) -> list[tuple[str, str]]:
    return [(m.group(1), m.group(2)) for m in
            re.finditer(r'<tg-emoji emoji-id="(\d+)">(.*?)</tg-emoji>', text, re.S)]


def ce_budget_ok(text: str, limit: int = 90) -> bool:
    """Server ~100 custom emoji/message ke baad plain kar deta hai."""
    return ce_count(text) <= limit


