# ══════════════════════════════════════════════════════════════════════════
#   🎴 UI ENGINE — HTML CARDS + ARTICLE / RICHTEXT + TABLES + ANIMATION
#   • card()      : Bot API HTML (b / code / blockquote expandable / tg-emoji)
#   • table()     : monospace aligned table (HTML <pre>) + PageBlockTable
#   • article()   : mini-markdown → PageBlock* descriptors (title, heading,
#                   table, checklist, toggle, quote, code, math, divider,
#                   coloured buttons) — native richtext rules pe
#   • sanitize()  : unsupported Instant-View blocks ko allowed shape me badalta
#   • animate()   : frame-by-frame edits (spinner + progress + premium emoji)
#   • render()    : ek hi hub — article → html card → plain, auto fallback
# ══════════════════════════════════════════════════════════════════════════

W = 34


def rule(ch: str = "─") -> str:
    return ch * W


def card(title: str, rows: Iterable[str] | None = None,
         footer: str | None = FOOTER, kicker: str | None = None) -> str:
    """Premium HTML card — har line pe rotating premium emoji, box rail, footer."""
    out = ["╭" + rule() + "╮"]
    if kicker:
        out.append(f"┃  {E('star')} <i>{esc(kicker.upper())}</i>")
        out.append("├" + rule() + "┤")
    out.append(f"┃  {E('crown')} <b>{esc(title)}</b>")
    out.append("├" + rule() + "┤")
    for r in (rows or []):
        out.append(f"┃  {r}" if r else "┃")
    if footer:
        out.append("├" + rule() + "┤")
        out.append(f"┃  {E('bolt')} {esc(footer)}")
    out.append("╰" + rule() + "╯")
    return "\n".join(out)


def kv(label: str, value: Any, bullet: str = "diamond") -> str:
    return f"{E(bullet)} <b>{esc(label)}</b> ‣ <code>{esc(value)}</code>"


def row(cmd: str, desc: str, bullet: str = "star") -> str:
    return f"{E(bullet)} <code>{esc(cmd)}</code> ‣ {sc(esc(desc))}"


def note(text: str, bullet: str = "white") -> str:
    return f"{E(bullet)} {esc(text)}"


def htmlrow(html_text: str, bullet: str = "white") -> str:
    """Pehle se HTML-formatted line (note() escaping nahi karega)."""
    return f"{E(bullet)} {html_text}"


def sep() -> str:
    return f"<code>{rule('─')}</code>"


def progress(pct: int, width: int = 10) -> str:
    pct = max(0, min(100, int(pct)))
    n = round(pct / 100 * width)
    return "▰" * n + "▱" * (width - n)


def table(headers: list[str], rows: list[list[Any]],
          align: list[str] | None = None) -> str:
    """Aligned monospace table — Telegram HTML me <pre> me, article me PageBlockTable."""
    align = align or ["l"] * len(headers)
    cols = len(headers)
    grid = [[str(x) for x in r] for r in rows]
    head = [str(h) for h in headers]
    widths = [max([len(head[i])] + [len(r[i]) for r in grid if i < len(r)] or [0])
              for i in range(cols)]

    def fmt(cells: list[str]) -> str:
        parts = []
        for i, c in enumerate(cells[:cols]):
            c = c if len(c) <= widths[i] else c[:widths[i]]
            a = align[i] if i < len(align) else "l"
            parts.append(c.center(widths[i]) if a == "c" else
                         c.rjust(widths[i]) if a == "r" else c.ljust(widths[i]))
        return "│ " + " │ ".join(parts) + " │"

    top = "┌" + "┬".join("─" * (w + 2) for w in widths) + "┐"
    mid = "├" + "┼".join("─" * (w + 2) for w in widths) + "┤"
    bot = "└" + "┴".join("─" * (w + 2) for w in widths) + "┘"
    lines = [top, fmt(head), mid]
    lines += [fmt(r + [""] * (cols - len(r))) for r in grid]
    lines.append(bot)
    return "<pre>" + _html.escape("\n".join(lines)) + "</pre>"


# ── article / richtext blocks ───────────────────────────────────────────────
# Descriptor = (kind, payload). Telethon available ho to TL objects ban jate
# hain; nahi to HTML preview / plain text. Isliye dependency optional hai.
ALLOWED_BLOCKS: set[str] = {
    "h1", "h2", "h3", "p", "table", "divider", "quote", "pre", "math",
    "list", "olist", "check", "toggle", "buttons", "caption", "think", "foot",
}
# Instant View-only blocks → bot rich message me reject hote hain
FORBIDDEN_MAP: dict[str, str] = {
    "title": "h1", "subtitle": "p", "kicker": "p", "header": "h3",
    "subheader": "h3", "authordate": "p", "related": "drop",
}


def sanitize_blocks(blocks: list[tuple[str, Any]]) -> list[tuple[str, Any]]:
    out: list[tuple[str, Any]] = []
    for kind, payload in blocks:
        kind = FORBIDDEN_MAP.get(kind, kind)
        if kind == "drop" or kind not in ALLOWED_BLOCKS:
            continue
        if kind == "table":
            rows = payload.get("rows", [])
            if len(rows) < 2:                      # 1-row table = empty box
                out.append(("p", " ⇒ " + " · ".join(
                    str(c) for c in (rows[0] if rows else []))))
                continue
        if kind == "pre" and not str(payload.get("text", "")).strip():
            continue
        out.append((kind, payload))
    return out


def article(text: str) -> list[tuple[str, Any]]:
    """Mini-markdown → article blocks (native richtext syntax)."""
    blocks: list[tuple[str, Any]] = []
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        ln = lines[i].rstrip()
        s = ln.strip()
        if not s:
            i += 1
            continue
        if s.startswith("@title "):
            blocks.append(("h1", {"text": s[7:]}))
        elif s.startswith("@kick "):
            blocks.append(("p", {"text": s[6:], "bold": True}))
        elif s.startswith("@sub "):
            blocks.append(("p", {"text": s[5:], "italic": True}))
        elif re.fullmatch(r"-{3,}", s):
            blocks.append(("divider", {}))
        elif re.match(r"^#{1,6}\s", s):
            lvl = len(s) - len(s.lstrip("#"))
            blocks.append((f"h{min(lvl, 3)}", {"text": s.lstrip("# ").strip()}))
        elif s.startswith("$$") and s.endswith("$$"):
            blocks.append(("math", {"text": s[2:-2]}))
        elif s.startswith("```"):
            lang = s[3:].strip()
            body = []
            i += 1
            while i < len(lines) and not lines[i].strip().startswith("```"):
                body.append(lines[i]); i += 1
            blocks.append(("pre", {"text": "\n".join(body), "lang": lang}))
        elif s.startswith("::: "):
            inner = []
            i += 1
            while i < len(lines) and not lines[i].strip().startswith(":::"):
                inner.append(lines[i]); i += 1
            blocks.append(("toggle", {"title": s[4:], "blocks": article("\n".join(inner))}))
        elif s.startswith("|"):
            tbl: list[list[str]] = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                cells = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                if not all(re.fullmatch(r":?-{2,}:?", c or "-") for c in cells):
                    tbl.append(cells)
                i += 1
            if tbl:
                blocks.append(("table", {"rows": tbl, "striped": True}))
            continue
        elif s.startswith("[[btn:"):
            m = re.match(r"\[\[btn:(blue|green|red|link)\]\]\s*(.*?)\s*\|\s*(\S+)", s)
            if m:
                blocks.append(("buttons", {"items": [(m.group(1), m.group(2), m.group(3))]}))
        elif s.startswith("> "):
            blocks.append(("quote", {"text": s[2:]}))
        elif re.match(r"^-\s+\[[ xX]\]", s):
            items = []
            while i < len(lines) and re.match(r"^\s*-\s+\[[ xX]\]", lines[i]):
                m = re.match(r"^\s*-\s+\[([ xX])\]\s*(.*)", lines[i])
                items.append((m.group(1).lower() == "x", m.group(2)))
                i += 1
            blocks.append(("check", {"items": items}))
            continue
        elif re.match(r"^-\s+", s):
            items = []
            while i < len(lines) and re.match(r"^\s*-\s+", lines[i]):
                items.append(re.sub(r"^\s*-\s+", "", lines[i])); i += 1
            blocks.append(("list", {"items": items}))
            continue
        elif re.match(r"^\d+\.\s+", s):
            items = []
            while i < len(lines) and re.match(r"^\s*\d+\.\s+", lines[i]):
                items.append(re.sub(r"^\s*\d+\.\s+", "", lines[i])); i += 1
            blocks.append(("olist", {"items": items}))
            continue
        else:
            blocks.append(("p", {"text": s}))
        i += 1
    return sanitize_blocks(blocks)


def blocks_to_html(blocks: list[tuple[str, Any]]) -> str:
    """Article blocks → standalone preview HTML (inline CSS, zero external)."""
    out: list[str] = []
    for kind, p in blocks:
        t = esc(p.get("text", "")) if isinstance(p, dict) else esc(p)
        if kind in ("h1", "h2", "h3"):
            out.append(f"<h{kind[-1]}>{t}</h{kind[-1]}>")
        elif kind == "p":
            tag = "b" if p.get("bold") else "i" if p.get("italic") else None
            out.append(f"<p>{f'<{tag}>{t}</{tag}>' if tag else t}</p>")
        elif kind == "divider":
            out.append("<hr>")
        elif kind == "quote":
            out.append(f"<blockquote>{t}</blockquote>")
        elif kind == "pre":
            out.append(f"<pre>{_html.escape(p.get('text',''))}</pre>")
        elif kind == "math":
            out.append(f"<div class='math'>{t}</div>")
        elif kind == "table":
            rows = p.get("rows", [])
            head = rows[0] if rows else []
            body = rows[1:]
            out.append("<div class='table" + (" striped" if p.get("striped") else "") + "'>")
            if head:
                out.append("<div class='row'>" + "".join(
                    f"<div class='cell th'>{esc(c)}</div>" for c in head) + "</div>")
            for r in body:
                out.append("<div class='row'>" + "".join(
                    f"<div class='cell'>{esc(c)}</div>" for c in r) + "</div>")
            out.append("</div>")
        elif kind in ("list", "olist"):
            tag = "ul" if kind == "list" else "ol"
            out.append(f"<{tag}>" + "".join(f"<li>{esc(x)}</li>" for x in p["items"]) + f"</{tag}>")
        elif kind == "check":
            out.append("<ul>" + "".join(
                f"<li><span class='cb'>{'✔' if done else '☐'}</span> {esc(x)}</li>"
                for done, x in p["items"]) + "</ul>")
        elif kind == "toggle":
            out.append(f"<details><summary>{esc(p['title'])}</summary>"
                       + blocks_to_html(p["blocks"]) + "</details>")
        elif kind == "buttons":
            for style, label, url in p["items"]:
                out.append(f"<a class='btn b-{style}' href='{esc(url)}'>{esc(label)}</a>")
        elif kind == "foot":
            out.append(f"<div class='foot'>{t}</div>")
        elif kind == "think":
            out.append(f"<div class='think'>{t}</div>")
    return "\n".join(out)


def blocks_to_rich_html(blocks: list[tuple[str, Any]]) -> str:
    """Article blocks → Telegram rich_message.html (Bot API 10.1+).
    Supported: <p> <b> <i> <code> <pre> <blockquote> <table bordered striped>
    <tr>/<th>/<td>, lists, <tg-emoji>, <hr>, coloured inline buttons."""
    out: list[str] = []
    for kind, p in blocks:
        t = esc(p.get("text", "")) if isinstance(p, dict) else esc(p)
        if kind in ("h1", "h2", "h3"):
            out.append(f"<h{kind[-1]}>{t}</h{kind[-1]}>")
        elif kind == "p":
            tag = "b" if p.get("bold") else "i" if p.get("italic") else None
            out.append(f"<p>{f'<{tag}>{t}</{tag}>' if tag else t}</p>")
        elif kind == "divider":
            out.append("<hr/>")
        elif kind == "quote":
            out.append(f"<blockquote>{t}</blockquote>")
        elif kind == "pre":
            out.append(f"<pre><code class='language-{esc(p.get('lang',''))}'>"
                       f"{_html.escape(p.get('text',''))}</code></pre>")
        elif kind == "math":
            out.append(f"<p><code>{t}</code></p>")
        elif kind == "table":
            rows = p.get("rows", [])
            attrs = " bordered striped" if p.get("striped") else " bordered"
            out.append(f"<table{attrs}>")
            for ri, r in enumerate(rows):
                cell = "th" if ri == 0 else "td"
                out.append("<tr>" + "".join(f"<{cell}>{esc(c)}</{cell}>" for c in r) + "</tr>")
            out.append("</table>")
        elif kind in ("list", "olist"):
            tag = "ul" if kind == "list" else "ol"
            out.append(f"<{tag}>" + "".join(f"<li>{esc(x)}</li>" for x in p["items"]) + f"</{tag}>")
        elif kind == "check":
            out.append("<ul>" + "".join(
                f"<li>{'☑' if done else '☐'} {esc(x)}</li>" for done, x in p["items"]) + "</ul>")
        elif kind == "toggle":
            out.append(f"<blockquote><p><b>{esc(p['title'])}</b></p>"
                       + blocks_to_rich_html(p["blocks"]) + "</blockquote>")
        elif kind == "buttons":
            out.append("<p>" + " ".join(
                f"<a href='{esc(url)}'>{esc(label)}</a>" for _, label, url in p["items"]) + "</p>")
        elif kind in ("foot", "think", "caption"):
            out.append(f"<p>{t}</p>")
    return "\n".join(out)


async def send_rich_message(chat: int, blocks: list[tuple[str, Any]]) -> tuple[bool, str]:
    """Asli article bhejo (sendRichMessage). Na chale to plain HTML fallback.
    Bot ko premium chahiye nahi; server API 10.1+ hona chahiye."""
    rich = blocks_to_rich_html(blocks)
    if RICH_UI and BOT_TOKEN and HAS_HTTPX:
        try:
            async with httpx.AsyncClient(timeout=20.0) as cl:
                r = await cl.post(
                    f"https://api.telegram.org/bot{BOT_TOKEN}/sendRichMessage",
                    json={"chat_id": chat, "rich_message": {"html": rich},
                          "disable_notification": True})
                data = r.json() if r.headers.get("content-type", "").startswith("application/json") else {}
                if r.status_code == 200 and data.get("ok"):
                    return True, "ʀɪᴄʜ ᴍᴇssᴀɢᴇ"
        except Exception as e:
            log.debug("sendRichMessage: %s", e)
    return False, "ʜᴛᴍʟ ᴄᴀʀᴅ ꜰᴀʟʟʙᴀᴄᴋ"


def blocks_to_telethon(blocks: list[tuple[str, Any]]) -> list[Any] | None:
    """Article blocks → real TL PageBlock* objects (Telethon ho to)."""
    if not HAS_TELETHON:
        return None
    T = types
    def T_(s: Any, bold: bool = False, italic: bool = False):
        v = T.TextPlain(str(s))
        return T.TextBold(v) if bold else T.TextItalic(v) if italic else v
    out: list[Any] = []
    for kind, p in blocks:
        try:
            if kind == "h1":   out.append(T.PageBlockHeading1(text=T_(p["text"])))
            elif kind == "h2": out.append(T.PageBlockHeading2(text=T_(p["text"])))
            elif kind == "h3": out.append(T.PageBlockHeading3(text=T_(p["text"])))
            elif kind == "p":
                parts = [T.TextPlain(str(p["text"]))]
                rt = T.TextConcat(texts=parts) if len(parts) > 1 else parts[0]
                out.append(T.PageBlockParagraph(text=rt))
            elif kind == "divider": out.append(T.PageBlockDivider())
            elif kind == "quote":
                out.append(T.PageBlockBlockquote(text=T_(p["text"]), caption=T.TextEmpty()))
            elif kind == "pre":
                out.append(T.PageBlockPreformatted(text=T_(p["text"]), language=p.get("lang","")))
            elif kind == "math": out.append(T.PageBlockMath(source=str(p["text"])))
            elif kind == "table":
                rows = []
                for ri, r in enumerate(p["rows"]):
                    rows.append(T.PageTableRow(cells=[T.PageTableCell(
                        header=(ri == 0), text=T_(c)) for c in r]))
                out.append(T.PageBlockTable(title=T.TextEmpty(), rows=rows,
                                            bordered=True, striped=bool(p.get("striped"))))
            elif kind in ("list", "olist"):
                it = (T.PageListItemText if kind == "list" else T.PageListOrderedItemText)
                items = [it(text=T_(x)) for x in p["items"]]
                out.append((T.PageBlockList if kind == "list" else
                            T.PageBlockOrderedList)(items=items))
            elif kind == "check":
                out.append(T.PageBlockList(items=[T.PageListItemText(
                    text=T_(x), checkbox=True, checked=bool(done))
                    for done, x in p["items"]]))
            elif kind == "toggle":
                out.append(T.PageBlockDetails(open=False, title=T_(p["title"]),
                                              blocks=blocks_to_telethon(p["blocks"]) or []))
            elif kind == "buttons":
                btns = []
                for style, label, url in p["items"]:
                    st = {"blue": T.RichButtonStyle(bg_primary=True),
                          "green": T.RichButtonStyle(bg_success=True),
                          "red": T.RichButtonStyle(bg_danger=True),
                          "link": T.RichButtonStyle(link=True)}.get(style)
                    btns.append(T.PageButton(text=T_(label),
                                type=T.InlineButtonTypeUrl(url=url), style=st))
                out.append(T.PageBlockButtonRow(buttons=btns))
        except Exception as e:
            log.debug("block %s skipped: %s", kind, e)
    return out


# ── animation engine ─────────────────────────────────────────────────────────
async def animate(msg: Any, title: str, rows: list[str] | None = None,
                  rounds: int = 5, delay: float = 0.34,
                  final: str | None = None) -> Any:
    """Har jagah animation — spinner + progress bar + premium emoji frames."""
    if not ANIM:
        if final:
            try: await msg.edit_text(final, parse_mode="HTML")
            except Exception: pass
        return msg
    for i in range(max(2, rounds)):
        pct = int((i + 1) / max(2, rounds) * 100)
        frame = card(title, [
            f"{E('rocket')} {FACES[min(i, len(FACES)-1)]} <b>ᴡᴏʀᴋɪɴɢ</b> · <code>{pct}%</code>",
            f"<code>[{UI_BARS[min(i, len(UI_BARS)-1)]}]</code>",
            f"{E('star')} {SPIN[i % len(SPIN)]} {sc('ᴘʀᴏᴄᴇssɪɴɢ')}",
        ] + list(rows or []), footer=None)
        try:
            await msg.edit_text(frame, parse_mode="HTML")
        except Exception:
            pass
        await asyncio.sleep(delay)
    if final:
        try: await msg.edit_text(final, parse_mode="HTML")
        except Exception: pass
    return msg


async def render(update: Any, ctx: Any, title: str, rows: list[str],
                 footer: str | None = FOOTER, animate_it: bool = True,
                 reply_markup: Any = None) -> Any:
    """Central render hub — har command yahin se card bhejta hai.
    Article path (Telethon premium account) → HTML card → plain text fallback."""
    html_card = card(title, rows, footer=footer)
    msg = None
    try:
        msg = await update.message.reply_text(
            card(title, [f"{E('wait')} {sc('ʀᴇɴᴅᴇʀɪɴɢ...')}"], footer=None),
            parse_mode="HTML")
    except Exception:
        try:
            msg = await update.message.reply_text(ce_strip(html_card))
        except Exception:
            return None
    if animate_it:
        await animate(msg, title, rows=rows[:2], rounds=4, final=html_card)
    else:
        try: await msg.edit_text(html_card, parse_mode="HTML")
        except Exception: pass
    if reply_markup is not None:
        try: await msg.edit_reply_markup(reply_markup=reply_markup)
        except Exception: pass
    return msg


