# ─── part 4 ────────────────────────────────────────────────────────────────


# ══════════════════════════════════════════════════════════════════════════
#   🔣 PREFIX ENGINE  ·  🤖 .addbot / SUB-SESSION HOSTING  ·  🔗 CLUSTER
#   • prefix KHUD se customize (~setprefix . / ! / 🌟 / koi bhi string)
#   • prefix ON / OFF  (off = bina prefix bhi command, owner + apna account)
#   • .addbot  = naya userbot account login (phone → code → 2FA → attach)
#   • addtoken = naya BOT token cluster me jodo, ID se connect karo
#   • har subbot ke apne handlers, apna contextvar proxy, health + reconnect
#   • sab kuch JSON me persist, owner DM report, main-bot guarded
# ══════════════════════════════════════════════════════════════════════════

BAAP_COMMANDS: set[str] = {
    "addbot", "delbot", "user", "subbots", "code", "c", "p", "pass", "resend",
    "cancelbot", "addtoken", "addtokens", "removetoken", "removetokens",
    "listbots", "bots", "connect", "botinfo", "syncall", "health", "reconnect",
    "setprefix", "prefix", "panel", "control", "sudo", "delsudo", "sudolist",
    "clearsudo", "login", "setsession", "session", "logout", "gcs", "groups",
    "gcdetail", "tasks", "ownerreport", "stats", "status", "listgc",
    "knownchats", "setdelay", "setbotname", "setbotbio", "setbotdesc",
    "setbotpfp", "shutdown", "multimode", "broadcast", "ui", "article",
    "design", "gcon", "gcoff", "setgameover", "addgameoverpfp", "leaveall",
}


def prefix_text() -> str:
    return str(PREFIX_STATE.get("prefix") or "~")


def prefix_regex() -> str:
    return re.escape(prefix_text())


def _looks_like_cmd(text: str) -> tuple[str, str]:
    """(command, args) — prefix ho ya na ho, dono handle."""
    t = (text or "").strip()
    if not t:
        return "", ""
    p = prefix_text()
    if p and t.startswith(p):
        body = t[len(p):].strip()
    elif t.startswith("/"):
        body = t[1:].strip()
    elif PREFIX_STATE.get("optional"):
        body = t
    else:
        return "", ""
    parts = body.split(None, 1)
    cmd = parts[0].lower().lstrip("/")
    cmd = re.sub(r"@[a-z0-9_]+$", "", cmd, flags=re.I)
    return cmd, (parts[1].strip() if len(parts) > 1 else "")


async def prefix_gate(update: Any, ctx: Any) -> None:
    """Prefix OFF (optional) me bina-prefix sirf owner / apna account."""
    if PREFIX_STATE.get("optional") is not True:
        return
    try:
        text = update.message.text or ""
    except Exception:
        return
    p = prefix_text()
    if text.startswith(p) or text.startswith("/"):
        return
    cmd, _ = _looks_like_cmd(text)
    if cmd and not is_owner(uid_of(update)):
        # sudo / baaki users ke liye bina-prefix band (userbot wala guard)
        try: await ctx.bot.send_message(chat_id(update),
                                      f"{E('no')} Bina-prefix sirf owner ke liye hai.")
        except Exception: pass
        raise _StopDispatch()


class _StopDispatch(Exception):
    """Internal: dispatcher aage na jaye."""


async def main_bot_guard(update: Any, ctx: Any) -> None:
    """Management / 'baap level' sirf main bot pe."""
    try:
        text = (update.message.text or "").strip()
    except Exception:
        return
    cmd, _ = _looks_like_cmd(text)
    if cmd in BAAP_COMMANDS and not is_main_bot(ctx):
        try:
            await update.message.reply_text(card(
                "🔒 ᴘʀɪᴠᴀᴛᴇ sʏsᴛᴇᴍ", [
                    kv("ʏᴇ sᴇᴄᴛɪᴏɴ", "sɪʀꜰ ᴍᴀɪɴ ʙᴏᴛ ᴘᴇ"),
                    note("NC / raid sab bots pe chalte hain."),
                    note("Management @Nikkkwa ke main bot pe."),
                ]), parse_mode="HTML")
        except Exception: pass
        raise _StopDispatch()


