NC_TASKS: dict[int, asyncio.Task] = {}
NC_STATE: dict[int, dict] = {}
NC_PULSE: dict[int, dict] = {}
NC_SEQ = itertools.count(1)
NC_LAST = [""]

FUSION_MAX_CONC = 4
FUSION_BURST = 6.0
FUSION_REFILL = 18.0
FUSION_FLOOD_CAP = 3.0
FUSION_GHOST_WAIT = 25.0
FUSION_TUNE_WINDOW = 2.0


def nc_pulse(bid: int) -> dict:
    p = NC_PULSE.get(bid)
    if p is None:
        p = {"flood_until": 0.0, "quarantine_until": 0.0,
             "tokens": FUSION_BURST, "last_refill": time.monotonic(),
             "ok": 0, "fails": 0, "renames": 0, "latency": 0.0}
        NC_PULSE[bid] = p
    return p


def nc_take(p: dict) -> bool:
    """Proactive throttle — RetryAfter aane se PEHLE."""
    now = time.monotonic()
    dt = now - p["last_refill"]
    if dt > 0:
        p["tokens"] = min(FUSION_BURST, p["tokens"] + dt * FUSION_REFILL)
        p["last_refill"] = now
    if p["tokens"] < 1.0:
        return False
    p["tokens"] -= 1.0
    return True


async def nc_wait(stop: asyncio.Event, timeout: float) -> None:
    try: await asyncio.wait_for(stop.wait(), timeout=max(0.001, timeout))
    except asyncio.TimeoutError: pass


# ── glitch wall builders (cross-hatch lattice + heart columns) ──────────────
def wall(atom: str, cols: int = 16, rows: int = 7,
         heart: str | None = None, heart_col: bool = False) -> str:
    lines = []
    for r in range(rows):
        ln = atom * cols
        if heart_col:
            ln = ln[:max(1, cols // 2)] + (heart or HEARTS[r % len(HEARTS)]) + ln[max(1, cols // 2):]
        lines.append(ln)
    return "\n".join(lines)


def glitch_name(style: int, base: str, seq: int) -> str:
    """10 alag glitch signatures — har ek ka apna atom, heart, filler, baap line."""
    a = GLITCH_ATOMS[style % len(GLITCH_ATOMS)]
    b = GLITCH_ATOMS[(style * 7 + 3) % len(GLITCH_ATOMS)]
    h = HEARTS[(seq + style) % len(HEARTS)]
    line = text_pick("nc_glitch", seq, target=base)
    s = seq
    if style == 0:      # X-cross lattice + heart column
        body = wall("⫷✖⫸", 9, 4, h, True)
    elif style == 1:    # cuneiform 𒀱ꪳ + pride hearts
        body = "\n".join((a + PRIDE[(s + i) % len(PRIDE)]) * 5 for i in range(4))
    elif style == 2:    # ﷽ / ꧅ dense long wall
        body = (a * 6 + h + b * 6 + "\n") * 4
    elif style == 3:    # ¿𑁍ࠬܓ monochrome + white hearts
        body = "\n".join((a * 8) + "🤍" + (b * 8) for _ in range(4))
    elif style == 4:    # vertical tall wall (newline se height)
        body = (a * 7 + "\n") * 8
    elif style == 5:    # checkerboard glitch
        body = "\n".join(("".join(
            GLITCH_ATOMS[(s + i + j) % len(GLITCH_ATOMS)] for j in range(9)))
            for i in range(4))
    elif style == 6:    # heart rain rows
        body = "\n".join((a * 3 + HEARTS[(s + i) % len(HEARTS)] * 3) * 3
                         for i in range(4))
    elif style == 7:    # invisible filler + tall glitch
        body = ("ㅤ" * 3 + a * 8 + "ㅤ" * 3 + "\n") * 4
    elif style == 8:    # musical glitch 𝄞‿︵⋅
        body = "\n".join((a + STARS[(s + i) % len(STARS)] + b) * 4 for i in range(4))
    else:               # full diagonal lattice
        body = "\n".join((a if (i + s) % 2 else b) * 11 for i in range(5))
    return fit(f"{base} {h} {line}\n{body} ·{s:05d}", 255)


def style_name(style: int, base: str, seq: int) -> str:
    """10 style NCs — font / emoji / flag / moon / crown / time / bar / rain."""
    wl, wr = random.choice(WRAP_L), random.choice(WRAP_R)
    g1, g2 = random.choice(GLYPHS), random.choice(GLYPHS)
    h = HEARTS[seq % len(HEARTS)]
    t = now_ist()
    s = seq
    line = text_pick("nc_style", s, target=base)
    if style == 0:   cand = f"{wl} {sb(base)} {wr} {h} {GLYPHS[s % len(GLYPHS)]}"
    elif style == 1: cand = f"{sc(base)} {h} {PRIDE[s % len(PRIDE)]} {line}"
    elif style == 2: cand = f"🚩 {base} {random.choice(['🏳️','🏴','🏁','🎌','🏳️‍🌈'])} {wl}{wr}"
    elif style == 3: cand = f"🌙 {mono(base)} {random.choice(['🌒','🌓','🌔','🌕','🌖','🌗','🌘'])} {g1}"
    elif style == 4: cand = f"👑 {sb(base)} 👑 {line} ♛"
    elif style == 5: cand = f"{random.choice(HEARTS)} {base} {random.choice(HEARTS)} {g2}"
    elif style == 6: cand = f"{mono(base)} · {g1}{g2} · {sb(line)}"
    elif style == 7: cand = f"{base} ⌁ {t} ⌁ {wl} {BARS[s % len(BARS)]}"
    elif style == 8: cand = f"{g1}{base}{g2} {BARS[s % len(BARS)]} {h}"
    else:            cand = f"{h}✦ {base} ✦{h} {'·' * (s % 5 + 1)}"
    return fit(f"{cand} ·{s:05d}", 255)


def ultra_name(style: int, base: str, seq: int) -> str:
    """5 ultra NCs — fusion / fire / god / war / quantum."""
    s = seq
    line = text_pick("nc_ultra", s, target=base)
    if style == 0:      # niknc — fusion wrap + atomic
        return fit(f"{WRAP_L[s % 12]}{GLYPHS[s % 30]}{sb(base)}{GLYPHS[(s*7) % 30]}{WRAP_R[s % 12]} ✦ {line} ·{s:05d}")
    if style == 1:      # nikfire — fire + glitch sparks
        return fit(f"🔥 {sb(base)} 🔥 {random.choice(GLITCH_ATOMS) * 4} 💥 {line} ·{s:05d}")
    if style == 2:      # nikgod — crown glyph lattice
        return fit(f"{'♛' * 3} {sb(base)} {'♛' * 3}\n{wall('⟦⫷✖⫸⟧', 6, 3)} ·{s:05d}")
    if style == 3:      # nikwar — swords + target
        return fit(f"⚔️ {sb(base)} ⚔️ {GLITCH_ATOMS[(s*5) % 30] * 6} 🎯 {line} ·{s:05d}")
    return fit(f"⧗ {mono(base)} ⧗ {BARS[s % len(BARS)]} {GLYPHS[(s*11) % 30]}⟡ {now_ist()} ·{s:05d}")


