def nc_factory(spec: dict, text: str, section: str | None = None,
               gawd: bool = False) -> Callable[[], str]:
    kind, idx = spec["kind"], spec["idx"]
    sec = section or ("nc_glitch" if kind == "glitch" else
                      "nc_style" if kind == "style" else "nc_ultra")
    def _make() -> str:
        s = next(NC_SEQ)
        cand = (glitch_name(idx, text, s) if kind == "glitch" else
                style_name(idx, text, s) if kind == "style" else
                ultra_name(idx, text, s))
        if gawd or TEXT_GAWD:
            cand = gawd_wrap(cand, s)
        if cand == NC_LAST[0]:
            cand = fit(cand + f"·{s}", 255)
        NC_LAST[0] = cand
        return cand
    return _make


async def nc_fire(cid: int, bot: Any, p: dict, name: str, st: dict) -> None:
    t0 = time.monotonic()
    try:
        await bot.set_chat_title(cid, name)
        p["ok"] += 1; p["renames"] += 1
        p["latency"] = p["latency"] * 0.8 + (time.monotonic() - t0) * 0.2
        st["renames"] += 1; st["seq"] += 1
        if st["desc"] and st["seq"] % 12 == 0:
            try:
                await bot.set_chat_description(cid, nc_desc(st))
                st["desc_ok"] += 1
            except Exception:
                st["desc_fail"] += 1
    except RetryAfter as e:
        wait = float(getattr(e, "retry_after", 1) or 1)
        p["fails"] += 1; st["floods"] += 1
        if wait <= st["ghost_wait"]:
            p["tokens"] = max(0.0, p["tokens"] - 0.5)
            await asyncio.sleep(random.uniform(0.001, 0.004))
        else:
            p["flood_until"] = time.monotonic() + min(wait, FUSION_FLOOD_CAP)
            p["quarantine_until"] = time.monotonic() + 2.0
            p["tokens"] = 0.0
            st["relay"] = (st["relay"] + 1) % max(1, len(st["bots"]))
            st["quarantines"] += 1
    except (BadRequest, Forbidden):
        p["fails"] += 1
        await asyncio.sleep(0.05)
    except asyncio.CancelledError:
        raise
    except Exception:
        p["fails"] += 1


def nc_desc(st: dict) -> str:
    return fit(f"⚡ {text_pick('desc', int(st.get('cid', 0)))} · {st['renames']} titles · "
               f"{len(st['bots'])} bots · @Nikkkwa", 255)


async def nc_worker(cid: int, bot: Any, idx: int, st: dict) -> None:
    bid = getattr(bot, "id", None) or id(bot)
    p = nc_pulse(bid)
    stop = st["stop"]
    await nc_wait(stop, idx * 0.04)
    pending: set = set()
    try:
        while not stop.is_set():
            now = time.monotonic()
            if now < p["flood_until"] or now < p["quarantine_until"]:
                await nc_wait(stop, 0.15); continue
            if not nc_take(p):
                await nc_wait(stop, 0.015); continue
            if st["relay_mode"] and len(st["bots"]) > 1 and idx % len(st["bots"]) != st["relay"]:
                await nc_wait(stop, 0.08)
            while len(pending) < st["conc"] and not stop.is_set():
                pending.add(asyncio.create_task(
                    nc_fire(cid, bot, p, st["name_fn"](), st)))
            if not pending:
                await asyncio.sleep(0); continue
            _done, pending = await asyncio.wait(
                pending, timeout=0.02, return_when=asyncio.FIRST_COMPLETED)
            if random.random() < 0.25:
                await asyncio.sleep(random.uniform(0.001, 0.006))
    except asyncio.CancelledError:
        pass
    finally:
        for t in pending: t.cancel()
        if pending: await asyncio.gather(*pending, return_exceptions=True)


async def nc_tuner(cid: int, st: dict) -> None:
    stop = st["stop"]
    while not stop.is_set():
        await nc_wait(stop, FUSION_TUNE_WINDOW)
        if stop.is_set(): break
        now = time.monotonic()
        dt = max(0.001, now - st["last_tune"])
        rps = (st["renames"] - st["last_renames"]) / dt
        st["last_renames"], st["last_tune"], st["rps"] = st["renames"], now, rps
        if rps >= st["best_rps"] * 0.98 and rps > 0:
            st["best_rps"] = max(st["best_rps"], rps)
            st["conc"] = min(FUSION_MAX_CONC, st["conc"] + 1)
        elif rps < st["best_rps"] * 0.6:
            st["conc"] = max(1, st["conc"] - 1); st["best_rps"] *= 0.9
        elif random.random() < 0.2:
            st["conc"] = min(FUSION_MAX_CONC, st["conc"] + 1)


async def nc_run(cid: int, st: dict) -> None:
    stop = st["stop"]
    workers = [asyncio.create_task(nc_worker(cid, b, i, st))
               for i, b in enumerate(st["bots"])]
    tuner = asyncio.create_task(nc_tuner(cid, st))
    try:
        await asyncio.gather(*workers, tuner, return_exceptions=True)
    except asyncio.CancelledError:
        raise
    finally:
        stop.set()
        for w in workers + [tuner]:
            if not w.done(): w.cancel()
        await asyncio.gather(*workers, tuner, return_exceptions=True)
        if NC_TASKS.get(cid) is asyncio.current_task(): NC_TASKS.pop(cid, None)
        if NC_STATE.get(cid) is st: NC_STATE.pop(cid, None)


def nc_parse(raw: str) -> tuple[dict, str]:
    f: dict[str, Any] = {"global": False, "desc": True, "ghost": True,
                        "conc": None, "gawd": False, "section": None}
    words = []
    for tok in raw.split():
        if tok == "--global": f["global"] = True
        elif tok == "--gawd": f["gawd"] = True
        elif tok.startswith("--text="): f["section"] = tok.split("=", 1)[1]
        elif tok == "--nodesc": f["desc"] = False
        elif tok == "--noghost": f["ghost"] = False
        elif tok.startswith("--conc="):
            try: f["conc"] = max(1, min(FUSION_MAX_CONC, int(tok.split("=", 1)[1])))
            except Exception: pass
        elif tok.startswith("--"): continue
        else: words.append(tok)
    return f, " ".join(words).strip()


def nc_start(cid: int, text: str, spec: dict, f: dict) -> dict | None:
    bots = pool()
    if not bots:
        return None
    if not GC_TOGGLES.get(str(cid), True):
        return None
    old = NC_TASKS.get(cid)
    if old and not old.done(): old.cancel()
    st: dict[str, Any] = {
        "cid": cid, "text": text[:120], "style": spec,
        "name_fn": nc_factory(spec, text[:120], f.get("section"), f.get("gawd", False)),
        "bots": bots, "stop": asyncio.Event(),
        "renames": 0, "seq": 0, "floods": 0, "quarantines": 0,
        "desc": f["desc"], "desc_ok": 0, "desc_fail": 0,
        "ghost_wait": FUSION_GHOST_WAIT if f["ghost"] else 0.0,
        "relay_mode": True, "relay": 0,
        "conc": f["conc"] or 1, "best_rps": 0.0, "rps": 0.0,
        "last_renames": 0, "last_tune": time.monotonic(),
        "started": time.monotonic(),
    }
    NC_STATE[cid] = st
    NC_TASKS[cid] = asyncio.create_task(nc_run(cid, st))
    return st


def nc_live() -> list[tuple[int, dict]]:
    return [(c, s) for c, s in NC_STATE.items()
            if NC_TASKS.get(c) and not NC_TASKS[c].done()]


def cancel(tasks: dict[int, asyncio.Task], cid: int) -> bool:
    t = tasks.pop(cid, None)
    if t and not t.done():
        t.cancel(); return True
    return False


def nc_stat_text() -> str:
    live = nc_live()
    if not live:
        return "\n".join([note("Koi NC live nahi."),
                          f"{pfx()} <code>{esc(prefix_text())}niknc &lt;txt&gt;</code> se start karo."])
    rows = []
    for cid, s in live[:6]:
        rows.append(f"{E('white')} <code>{cid}</code> · {s['renames']} titles · "
                    f"{s['rps']:.1f}/s · c{s['conc']} · {len(s['bots'])} bots · "
                    f"{int(time.monotonic()-s['started'])}s")
    rows.append(f"{E('globe')} total <b>{sum(s['renames'] for _, s in live)}</b> titles · "
                f"flood {sum(s['floods'] for _, s in live)} · "
                f"quarantine {sum(s['quarantines'] for _, s in live)}")
    return "\n".join(rows)


async def cmd_nc(update: Any, ctx: Any, style: str = "niknc",
                 force_global: bool = False) -> None:
    if not is_auth(uid_of(update)): return
    f, text = nc_parse(arg(update))
    if force_global: f["global"] = True
    spec = NC_STYLES.get(NC_ALIASES.get(style, style), NC_STYLES["niknc"])
    if not text:
        return await render(update, ctx, f"⚔️ {sb(style.upper())} · ᴜsᴀɢᴇ", [
            row(f"{prefix_text()}{style} <txt>", spec["desc"]),
            note("Flags: --global · --nodesc · --noghost · --conc=4 · --gawd · --text=<sec>"),
            row(f"{prefix_text()}stopniknc", "rok do"),
            row(f"{prefix_text()}nikncstat", "live telemetry"),
            sep(), note(f"{len(NC_STYLES)} apne NC · {len(GLITCH_ATOMS)} glitch atoms · "
                        f"{len(HEARTS)} hearts · {len(EMOJI_IDS)} premium emoji"),
        ])
    cid = chat_id(update)
    private = is_private(update)
    if not private: KNOWN_CHATS.add(cid); save_json("chats.json", sorted(KNOWN_CHATS))
    else: f["global"] = True
    cids = sorted(KNOWN_CHATS) if f["global"] else [cid]
