async def cmd_fwdspam(update: Any, ctx: Any) -> None:
    """~fwdspam <n> <txt> — forward spam (forward + send mix)."""
    raw = arg(update).strip()
    cid = chat_id(update)
    if raw.lower() in ("off", "stop"):
        cancel(FWD_TASKS, cid)
