async def cmd_spam(update: Any, ctx: Any) -> None:
    raw = arg(update).strip()
    cid = chat_id(update)
    if raw.lower() in ("off", "stop"):
        cancel(SPAM_TASKS, cid)
        return await render(update, ctx, "🛑 sᴘᴀᴍ ʙᴀɴᴅ", [kv("ɢᴄ", cid)])
    parts = raw.split(None, 1)
    n = int(parts[0]) if parts and parts[0].isdigit() else 3
    n = max(1, min(40, n))
    text = parts[1].strip() if len(parts) > 1 else text_pick("spam", cid)
    delay = LOOP_DELAY.get(cid, 0.4)
    stop = asyncio.Event()
    async def _run() -> None:
        while not stop.is_set():
            for b in pool():
                if stop.is_set(): break
                try:
                    for _ in range(n): await b.send_message(cid, fit(text if raw else text_pick("spam", cid)))
                except Exception: pass
            await nc_wait(stop, delay)
    _start_loop(SPAM_TASKS, cid, _run)
    await render(update, ctx, "🔥 sᴘᴀᴍ ʟɪᴠᴇ", [
        kv("ʙᴜʀsᴛ", n), kv("ᴅᴇʟᴀʏ", f"{delay}s"), kv("ʙᴏᴛs", len(pool())),
        row(f"{prefix_text()}spam off", "rok do")])


