async def cmd_leave(update: Any, ctx: Any) -> None:
    """~leave [cid|all] — pending alias, ab poora hai."""
    raw = arg(update).strip()
    targets = sorted(KNOWN_CHATS) if raw.lower() in ("all", "*") else [
        int(raw)] if raw.lstrip("-").isdigit() else [chat_id(update)]
    left = 0
    for c in targets:
        for b in pool():
            try: await b.leave_chat(c); left += 1; break
            except Exception: continue
    KNOWN_CHATS.difference_update(targets)
    save_json("chats.json", sorted(KNOWN_CHATS))
    await render(update, ctx, "🚪 ʟᴇᴀᴠᴇ", [kv("ɢᴄs", len(targets)), kv("ʟᴇꜰᴛ", left)])


