async def cmd_gctoggle(update: Any, ctx: Any, on: bool) -> None:
    raw = arg(update).strip()
    cids = sorted(KNOWN_CHATS) if raw.lower() in ("all", "*") else [
        int(x) for x in re.findall(r"-?\d{6,}", raw)] or [chat_id(update)]
    for c in cids:
        GC_TOGGLES[str(c)] = on
        if not on: await cancel_all(c)
    save_json("gc_toggles.json", GC_TOGGLES)
    await render(update, ctx, "🎚 ᴘᴇʀ-ɢᴄ ᴛᴏɢɢʟᴇ", [
        kv("ᴍᴏᴅᴇ", "🟢 ᴏɴ" if on else "🔴 ᴏꜰꜰ"), kv("ɢᴄs", len(cids)),
        *[note(str(c)) for c in cids[:8]]])


