async def cmd_tasks(update: Any, ctx: Any) -> None:
    rows = []
    for label, m in TASK_MAPS:
        live = [(c, t) for c, t in m.items() if t and not t.done()]
        rows.append(kv(label, len(live)))
    rows.append(sep())
    rows.append(htmlrow(f"<b>{esc('Live NC telemetry')}</b>"))
    rows.append(nc_stat_text() if nc_live() else "")
    await render(update, ctx, "⚡ ᴛᴀsᴋ ɪɴᴛᴇʟ", rows)


