def menu_page(i: int) -> str:
    icon, title, rows = MENU_SECTIONS[i]
    body = [f"{icon} <b>{sc(esc(title))}</b>", sep()]
    for cmd, desc in rows:
        body.append(f"{E('star')} <code>{esc(p(cmd))}</code> ‣ {sc(esc(desc))}")
    body += [sep(), note(f"sᴇᴄᴛɪᴏɴ {i + 1}/{len(MENU_SECTIONS)} · {FOOTER}")]
    return card(f"{BRAND} · ᴍᴇɴᴜ", body, footer=None)


def menu_index() -> str:
    body = [f"{E('crown')} <b>{sb('ᴄᴏᴍᴍᴀɴᴅ ɪɴᴅᴇx')}</b>", sep()]
    for i, (icon, title, rows) in enumerate(MENU_SECTIONS, 1):
        body.append(f"{icon} <code>m{i}</code> ‣ {sc(esc(title))} · {len(rows)} rows")
    body += [sep(), note(f"{len(NC_STYLES)} NC · {len(MENU_SECTIONS)} sections · "
                         f"{len(_CE_ALL)} premium ids")]
    return card(f"{BRAND} · ɪɴᴅᴇx", body)


