async def cmd_article(update: Any, ctx: Any) -> None:
    """~article <text> / md / html / demo / read / check / tpl."""
    raw = arg(update).strip()
    if not raw or raw == "help":
        return await render(update, ctx, "📄 ᴀʀᴛɪᴄʟᴇ · ʀɪᴄʜᴛᴇxᴛ", [
            row(f"{p('article')} <text>", "seedha article"),
            row(f"{p('article')} demo", "sample (tables + buttons)"),
            row(f"{p('article')} md <markdown>", "server parse"),
            row(f"{p('article')} html <html>", "html parse"),
            row(f"{p('article')} read", "reply article → text"),
            row(f"{p('design')} vault <title> | url", "template"),
            row(f"{p('article')} check", "support check"),
            sep(), note("@title · # heading · |table| · - [x] checklist · > quote · ::: toggle"),
        ])
    if raw == "check":
        return await render(update, ctx, "📄 ᴀʀᴛɪᴄʟᴇ ᴄʜᴇᴄᴋ", [
            kv("ʀɪᴄʜᴜɪ", "ᴏɴ" if RICH_UI else "ᴏꜰꜰ"),
            kv("ᴛᴇʟᴇᴛʜᴏɴ", "ʀᴇᴀᴅʏ" if HAS_TELETHON else "ᴏᴘᴛɪᴏɴᴀʟ (ꜰᴀʟʟʙᴀᴄᴋ ᴏɴ)"),
            kv("ᴘʀᴇᴍɪᴜᴍ", "ᴏɴ" if PREMIUM_EMOJI else "ᴏꜰꜰ"),
            kv("ᴀɴɪᴍᴀᴛɪᴏɴ", "ᴏɴ" if ANIM else "ᴏꜰꜰ"),
            note("Bot ko premium chahiye nahi; user account ko chahiye."),
        ])
    body = ARTICLE_DEMO if raw == "demo" else (raw.split(None, 1)[1] if raw.startswith(("md ", "html ")) else raw)
    blocks = article(body)
    tl = blocks_to_telethon(blocks) if (RICH_UI and HAS_TELETHON) else None
    sent, mode = await send_rich_message(chat_id(update), blocks)
    if not sent:                       # plain HTML card fallback (hamesha kaam kare)
        try:
            await update.message.reply_text(blocks_to_html(blocks).replace(
                "<h1>", "<b>").replace("</h1>", "</b>"), parse_mode="HTML")
        except Exception:
            pass
    await render(update, ctx, "📄 ᴀʀᴛɪᴄʟᴇ ʙᴜɪʟᴅᴇʀ", [
        kv("ʙʟᴏᴄᴋs", len(blocks)),
        kv("ᴛʏᴘᴇs", ", ".join(sorted({k for k, _ in blocks}))[:90]),
        kv("ᴛʟ ᴏʙᴊᴇᴄᴛs", len(tl) if tl else "ᴏᴘᴛɪᴏɴᴀʟ"),
        kv("ᴅᴇʟɪᴠᴇʀʏ", mode),
        kv("sᴀɴɪᴛɪᴢᴇᴅ", "✅ ɴᴏ ɪɴsᴛᴀɴᴛ-ᴠɪᴇᴡ ʙʟᴏᴄᴋs"),
        sep(), note("32,768 chars · 500 blocks · 20 columns · ~100 custom emoji"),
        note("Article na chale to HTML card fallback automatic hai."),
    ])


