async def handle_panel_callback(update: Any, ctx: Any) -> None:
    q = getattr(update, "callback_query", None)
    if not q or not getattr(q, "data", ""): return
    cb_uid = int(getattr(getattr(q, "from_user", None), "id", 0) or 0)
    if not is_auth(cb_uid) or not is_main_bot(ctx):
        try: await q.answer("Main bot / owner only", show_alert=True)
        except Exception: pass
        return
    action = q.data[2:]
    try: await q.answer()
    except Exception: pass
    text = {
        "status": card("📊 sᴛᴀᴛᴜs", [kv("ᴜᴘᴛɪᴍᴇ", uptime_str()),
                                    kv("ʙᴏᴛs", len(pool())), kv("ɢᴄs", len(KNOWN_CHATS))]),
        "tasks": card("⚡ ᴛᴀsᴋs", [nc_stat_text()]),
        "gcs": card("💬 ɢᴄs", [kv("ᴋɴᴏᴡɴ", len(KNOWN_CHATS)),
                               *[note(str(c)) for c in sorted(KNOWN_CHATS)[:10]]]),
        "connect": card("🔗 ᴄᴏɴɴᴇᴄᴛ", [kv("ᴛᴏᴋᴇɴ ʙᴏᴛs", len(BOT_TOKENS)),
                                      kv("sᴜʙʙᴏᴛs", len(SUBBOTS))]),
        "nikncstat": card("⚔️ ꜰᴜsɪᴏɴ", [nc_stat_text()]),
        "stopall": card("🛑 sᴛᴏᴘ", [note("~stopall / ~stopniknc use karo")]),
        "ui": card("🎬 ᴜɪ", [note("~ui animated dashboard")]),
        "article": card("📄 ᴀʀᴛɪᴄʟᴇ", [note("~article demo")]),
        "prefix": card("🔣 ᴘʀᴇꜰɪx", [kv("ᴄᴜʀʀᴇɴᴛ", prefix_text()),
                                     kv("ᴍᴏᴅᴇ", "ᴏꜰꜰ" if PREFIX_STATE.get("optional") else "ᴏɴ")]),
        "emoji": card("💎 ᴇᴍᴏᴊɪ", [kv("ᴀʟᴛs", len(EMOJI_IDS)),
                                   kv("ɪᴅs", len(_CE_ALL)), note("Har prefix ko nayi id")]),
        "menu": menu_index(),
        "refresh": card("🔄 ʀᴇꜰʀᴇsʜ", [kv("ᴛɪᴍᴇ", now_ist())]),
    }.get(action)
    if not text: return
    try: await q.message.edit_text(text, parse_mode="HTML", reply_markup=panel_keyboard())
    except Exception: pass


# ── profile (group → all · DM → pick / --all) ────────────────────────────────
PROFILE_METHODS: dict[str, str] = {
    "name": "set_my_name", "bio": "set_my_short_description",
    "desc": "set_my_description", "pfp": "set_my_profile_photo",
}


async def cmd_profile(update: Any, ctx: Any, kind: str = "name") -> None:
    if not is_owner(uid_of(update)): return
    raw = arg(update).strip()
    targets = pool()
    if is_private(update) and "--all" not in raw and not re.match(r"^#\d+|^@", raw):
        return await render(update, ctx, "🤖 ᴘʀᴏꜰɪʟᴇ ᴘɪᴄᴋᴇʀ", [
            note("DM me: kaunsa bot? (management main bot pe)"),
            row(f"{p('setbot'+kind)} --all <txt>", "sab bots"),
            row(f"{p('setbot'+kind)} #2 <txt>", "bot #2"),
            row(f"{p('setbot'+kind)} @bot <txt>", "username se"),
        ], reply_markup=panel_keyboard())
    if "--all" in raw:
        raw = raw.replace("--all", "", 1).strip()
    elif raw.startswith("#") and raw[1:2].isdigit():
        n = int(re.match(r"#(\d+)", raw).group(1))
        targets = targets[n - 1:n]
        raw = raw.split(None, 1)[1] if " " in raw else raw
    ok = 0
    for b in targets:
        try:
            if kind == "pfp": continue
            await getattr(b, PROFILE_METHODS[kind])(raw[:250])
            ok += 1
        except Exception: pass
