async def cmd_sudo(update: Any, ctx: Any) -> None:
    if not is_owner(uid_of(update)): return
    raw = arg(update).strip()
    uid = 0
    try: uid = int(update.message.reply_to_message.from_user.id)
    except Exception: pass
    if not uid and raw.lstrip("@").isdigit(): uid = int(raw.lstrip("@"))
    if not uid and "@" in raw:
        uid = int(next((v.get("id", 0) for k, v in KNOWN_USERS.items()
                        if k.lower() == raw.lstrip("@").lower()), 0))
    if not uid:
        return await render(update, ctx, "👥 sᴜᴅᴏ", [
            note("User pe reply karo, ya ID / @username do.")])
    SUDO_USERS.add(uid); save_json("sudo.json", sorted(SUDO_USERS))
    await render(update, ctx, "👥 sᴜᴅᴏ ᴀᴅᴅᴇᴅ", [kv("ɪᴅ", uid), kv("ᴛᴏᴛᴀʟ", len(SUDO_USERS))])


