async def cmd_fjoin(update: Any, ctx: Any) -> None:
    """Real MTProto join — CheckChatlistInvite → JoinChannel + FloodWait retry."""
    link = arg(update).strip()
    if not link:
        return await render(update, ctx, "🔗 ꜰᴊᴏɪɴ", [
            row(f"{p('fjoin')} https://t.me/+...", "invite link"),
            row(f"{p('joinall')}", "saved links sab"),
            note("Pyrogram user-session se hota hai; bot token se nahi.")])
    ok, note_txt = False, "Pyrogram session nahi hai (~setsession karo)."
    try:
        from pyrogram import Client
        from pyrogram.raw.functions.messages import CheckChatlistInvite, ImportChatInvite
        from pyrogram.raw.functions.channels import JoinChannel
        from pyrogram.errors import FloodWait
        sess = USERBOT_SESSION.get("session")
        if sess and API_ID and API_HASH:
            async with Client(":memory:", API_ID, API_HASH, session_string=sess,
                              in_memory=True) as cl:
                h = link.rsplit("/", 1)[-1].lstrip("+")
                try:
                    info = await cl.invoke(CheckChatlistInvite(invite=h))
                    ch = getattr(info, "chatlist", None) or getattr(info, "chats", [None])[0]
                    await cl.invoke(JoinChannel(channel=await cl.resolve_peer(
                        getattr(ch, "id", 0))))
                except Exception:
                    await cl.invoke(ImportChatInvite(h))
                ok = True
            note_txt = "✅ MTProto join ho gaya."
    except ImportError:
        note_txt = "Pyrogram install nahi hai (requirements me hai)."
    except Exception as e:
        note_txt = err_txt(e, 100)
    await render(update, ctx, "🔗 ꜰᴊᴏɪɴ ʀᴇsᴜʟᴛ", [
        kv("ʟɪɴᴋ", esc(link[:50])), kv("sᴛᴀᴛᴜs", "🟢" if ok else "🔴"),
        note(note_txt)])


