# ── self-test (bina kisi dependency ke chal jata hai) ────────────────────────
async def selftest() -> int:
    ok = 0
    def chk(label: str, cond: bool, extra: str = "") -> None:
        nonlocal ok
        print(("  ✅ " if cond else "  ❌ ") + label + (f"  {extra}" if extra else ""))
        if cond: ok += 1
        else: raise AssertionError(label)

    print("=== ɴɪᴋ ʙᴏᴛ · sᴇʟꜰ-ᴛᴇsᴛ ===")
    chk("emoji pool", len(EMOJI_IDS) >= 300 and len(_CE_ALL) >= 1500,
        f"{len(EMOJI_IDS)} alts / {len(_CE_ALL)} ids")
    ids = [ce_id("🌟") for _ in range(30)]
    chk("rotating custom id", len(set(ids)) >= 25, f"{len(set(ids))}/30 unique")
    chk("<tg-emoji> html", ce("🌟").startswith('<tg-emoji emoji-id="'), ce("🌟")[:48])
    chk("ce strip", "🌟" in ce_strip(ce("🌟")))
