def target_id(update: Any) -> int:
    """Reply / @username / numeric ID — teeno se target nikaalo."""
    try:
        r = update.message.reply_to_message
        if r and getattr(r, "from_user", None):
            return int(r.from_user.id)
    except Exception: pass
    raw = arg(update).strip().lstrip("@")
    if raw.isdigit() or (raw.startswith("-") and raw[1:].isdigit()):
        return int(raw)
    for k, v in KNOWN_USERS.items():
        if k.lower().lstrip("@") == raw.lower():
            return int(v.get("id", 0) or 0)
    return 0


