async def _mod(update: Any, ctx: Any, action: str) -> None:
    """Moderation core — har action pool() ke sab bots se try, premium report card."""
    cid, tid = chat_id(update), target_id(update)
    if not tid and action not in ("locks", "purgeall", "purgeme", "tagall", "staff"):
        return await render(update, ctx, f"🛡 {action.upper()}", [
            note("User pe reply karo ya ID / @username do.")])
    ok = 0
    for b in pool():
        try:
            if action == "ban": await b.ban_chat_member(cid, tid)
            elif action == "unban": await b.unban_chat_member(cid, tid, only_if_banned=True)
            elif action == "kick":
                await b.ban_chat_member(cid, tid); await b.unban_chat_member(cid, tid)
            elif action == "mute": await b.restrict_chat_member(
                cid, tid, permissions={"can_send_messages": False})
            elif action == "unmute": await b.restrict_chat_member(
                cid, tid, permissions={"can_send_messages": True,
                                       "can_send_media_messages": True,
                                       "can_send_other_messages": True})
            elif action == "promote": await b.promote_chat_member(
                cid, tid, can_manage_chat=True, can_delete_messages=True,
                can_restrict_members=True, can_pin_messages=True)
            elif action == "demote": await b.promote_chat_member(
                cid, tid, can_manage_chat=False, can_delete_messages=False,
                can_restrict_members=False, can_pin_messages=False)
            elif action == "pin":
                m = getattr(update.message, "reply_to_message", None)
                if m: await b.pin_chat_message(cid, m.message_id)
            elif action == "unpin": await b.unpin_chat_message(cid)
            ok += 1
        except Exception: pass
    if action == "ban": GBAN_LIST.add(tid) if "--global" in arg(update) else None
    if action == "unban": GBAN_LIST.discard(tid)
    save_json("gban.json", sorted(GBAN_LIST))
    await render(update, ctx, f"🛡 {action.upper()}", [
        kv("ᴜsᴇʀ", tid or "—"), kv("ɢᴄ", cid), kv("ʙᴏᴛs ᴏᴋ", f"{ok}/{len(pool())}"),
        kv("ᴀᴄᴛɪᴏɴ", "✅ ᴅᴏɴᴇ"),
    ])


def _mod_cmd(action: str) -> Callable[[Any, Any], Any]:
    async def _f(u: Any, c: Any) -> None: return await _mod(u, c, action)
    return _f


