async def cmd_stop_any(update: Any, ctx: Any) -> None:
    """Har legacy stop* alias — NC + raid sab loops band (card ke saath)."""
    name = _looks_like_cmd(getattr(getattr(update, "message", None), "text", "") or "")[0]
    return await cmd_stopalias(update, ctx, name)


async def cmd_legacy(update: Any, ctx: Any) -> None:
    """Ek resolver — 170+ legacy names ko real premium behaviour deta hai."""
    name = _looks_like_cmd(getattr(getattr(update, "message", None), "text", "") or "")[0]
    target = LEGACY_ALIAS.get(name)
    nc = LEGACY_NC.get(name)
    if nc and name not in LEGACY_ALIAS:
        return await cmd_nc(update, ctx, nc)
    if target and target.startswith("_"):
        fn = CUSTOM_COMMANDS.get(target)
        if fn: return await fn(update, ctx)
    if target and not target.startswith("_"):
        fn2 = SIMPLE_COMMANDS.get(target)
        if fn2 and fn2 is not cmd_legacy: return await fn2(update, ctx)
    return await cmd_help(update, ctx)


BCDB: dict[str, str] = load_json("bcdb.json", {})


async def cmd_bcdb(update: Any, ctx: Any, mode: str) -> None:
    """Broadcast DB — target chats save / delete / list."""
    raw = arg(update).strip()
    parts = raw.split(None, 1)
    key = parts[0] if parts else ""
    if mode == "add" and key:
        BCDB[key] = parts[1] if len(parts) > 1 else str(chat_id(update))
    elif mode == "del":
        BCDB.pop(key, None)
    save_json("bcdb.json", BCDB)
    await render(update, ctx, "📇 ʙʀᴏᴀᴅᴄᴀsᴛ ᴅʙ", [
        kv("ᴍᴏᴅᴇ", mode), kv("ᴇɴᴛʀɪᴇs", len(BCDB)),
        *[htmlrow(f"<code>{esc(k)}</code> → <code>{esc(v)}</code>")
          for k, v in list(BCDB.items())[:10]]])


