def _install_coverage() -> None:
    """Sab legacy names register karo — koi bhi command 'unknown' na ho."""
    n = 0
    for name in set(LEGACY_ALIAS) | set(LEGACY_NC):
        if name in GHATIYA_EXCLUDED or name in SIMPLE_COMMANDS or name in NC_STYLES:
            continue
        SIMPLE_COMMANDS[name] = cmd_legacy
        n += 1
    for alias, style in LEGACY_NC.items():
        if style in NC_STYLES and alias not in NC_ALIASES:
            NC_ALIASES[alias] = style
    log.info("coverage layer: +%d legacy commands · total %d direct + %d NC aliases",
             n, len(SIMPLE_COMMANDS), len(NC_ALIASES))


_install_coverage()


