TEXT_LEVEL: dict[str, int] = load_json("text_level.json", {})   # cid -> 0/1/2
GAWD_PREFIX: tuple[str, ...] = (
    "👑 ɴɪᴋ ɢᴀᴡᴅ · ", "⚡ ɢᴀᴡᴅ ᴍᴏᴅᴇ · ", "🔥 ɴɪᴋ ɪs ᴛʜᴇ ꜰɪɴᴀʟ ʙᴏss · ",
    "𒀱ꪳ ɴɪᴋ ɢᴀᴡᴅ 𒀱ꪳ · ", "⫷✖⫸ ɴɪᴋ ɢᴀᴡᴅ ⫷✖⫸ · ",
)
GAWD_TAIL: tuple[str, ...] = (
    " · ɴᴏ ᴄᴏᴍᴘᴇᴛɪᴛɪᴏɴ", " · ɢᴄ ʜᴀᴍᴀᴀʀᴀ", " · 25 ɴᴄ ʟɪᴠᴇ",
    " · @Nikkkwa", " · ʙᴀᴀᴘ ᴡᴀʀ ᴍᴏᴅᴇ",
)


def bank(section: str) -> tuple[str, ...]:
    base = TEXT_BANKS.get(section, ())
    extra = tuple(TEXT_CUSTOM.get(section, ()))
    return base + extra


def _tier(cid: int) -> int:
    return 2 if TEXT_GAWD else int(TEXT_LEVEL.get(str(cid), 0))


def text_pick(section: str, cid: int = 0, target: str = "",
              gawd: bool | None = None) -> str:
    """Ek template — kabhi repeat nahi (rotate), kabhi random (mode), hamesha NIK."""
    pool_t = bank(section)
    if not pool_t:
        return "👑 ɴɪᴋ ʙᴀᴀᴘ · ɴᴏ ᴄᴏᴍᴘᴇᴛɪᴛɪᴏɴ"
    key = f"{section}:{cid}"
    if TEXT_MODE == "random" or (TEXT_MODE == "mix" and random.random() < 0.35):
        idx = random.randrange(len(pool_t))
    else:
        idx = TEXT_CURSOR.get(key, 0) % len(pool_t)
        TEXT_CURSOR[key] = (idx + 1) % len(pool_t)
    t = pool_t[idx]
    if target:
        t = t.replace("{target}", target)
    else:
        t = t.replace("{target}", "ᴛᴀʀɢᴇᴛ")
    tier = _tier(cid) if gawd is None else (2 if gawd else _tier(cid))
    if tier >= 1:
        t = ("👑 NIK · " if "nik" not in fold_text(t) else "") + t
    if tier >= 2:
        t = (GAWD_PREFIX[idx % len(GAWD_PREFIX)] + t[:200] +
             GAWD_TAIL[idx % len(GAWD_TAIL)] +
             "  " + WRAP_L[idx % len(WRAP_L)] + "⫷✖⫸" + WRAP_R[idx % len(WRAP_R)])
    return fit(t, 255)


_SMALL_MAP = str.maketrans({
    'ᴀ':'a','ʙ':'b','ᴄ':'c','ᴅ':'d','ᴇ':'e','ꜰ':'f','ɢ':'g','ʜ':'h','ɪ':'i',
    'ᴊ':'j','ᴋ':'k','ʟ':'l','ᴍ':'m','ɴ':'n','ᴏ':'o','ᴘ':'p','ǫ':'q','ʀ':'r',
    'ꜱ':'s','ᴛ':'t','ᴜ':'u','ᴠ':'v','ᴡ':'w','ʏ':'y','ᴢ':'z','Ɱ':'m','ƛ':'a',
    'Ӈ':'h','Ɲ':'n','Ɠ':'g','Ʀ':'r','Ɩ':'i','Є':'e','Ɓ':'b','Ɗ':'d','Ƙ':'k',
    'Ơ':'o','Ƈ':'c','Ƭ':'t','ⱦ':'t','я':'r','ɠ':'g','н':'h','ɑ':'a','υ':'u',
    'σ':'o','т':'t','в':'b','і':'i','ѕ':'s','а':'a','е':'e','о':'o','р':'p',
    'с':'c','у':'y','х':'x','ք':'p','ҩ':'o','ɨ':'i','ᵃ':'a','ᵐ':'m','ᶠ':'f',
    'ᵇ':'b','ᶜ':'c','ᵈ':'d','ᵉ':'e','ᵍ':'g','ʰ':'h','ⁱ':'i','ʲ':'j','ᵏ':'k',
    'ˡ':'l','ⁿ':'n','ᵒ':'o','ᵖ':'p','ʳ':'r','ˢ':'s','ᵗ':'t','ᵘ':'u','ᵛ':'v',
    'ʷ':'w','ˣ':'x','ʸ':'y','ᶻ':'z','ꓭ':'b','ꓐ':'b','Ɐ':'a','ẞ':'b'})


def fold_text(s: str) -> str:
    """Naam-check: mathematical fonts + small caps + modifier letters → ASCII."""
    n = unicodedata.normalize("NFKC", s).lower()
    return n.translate(_SMALL_MAP)


def gawd_wrap(s: str, seq: int = 0) -> str:
    return fit(GAWD_PREFIX[seq % len(GAWD_PREFIX)] + s[:190] +
               GAWD_TAIL[seq % len(GAWD_TAIL)], 255)


def text_stats() -> dict[str, int]:
    return {k: len(bank(k)) for k in TEXT_META}


def text_table() -> str:
    rows = [[k.upper(), str(len(bank(k))), TEXT_META[k][1]]
            for k in TEXT_META]
    return table(["sᴇᴄᴛɪᴏɴ", "ᴛᴇxᴛs", "ꜰᴇᴀᴛᴜʀᴇ"], rows, align=["l", "r", "l"])


def text_panel_keyboard() -> Any:
    if not HAS_PTB: return None
    B = InlineKeyboardButton
    return InlineKeyboardMarkup([
        [B("⚔️ ɴᴄ", callback_data="t:nc_glitch"), B("🎞 sʟɪᴅᴇs", callback_data="t:slides"),
         B("💥 sᴘᴀᴍ", callback_data="t:spam")],
        [B("🌀 sᴡɪᴘᴇ", callback_data="t:swipe"), B("💬 ʀᴇᴘʟʏ", callback_data="t:reply"),
         B("📨 ꜰᴡᴅ", callback_data="t:fwdspam")],
        [B("👑 ʙᴀᴀᴘ", callback_data="t:baap"), B("🕉 ɢᴀᴡᴅ", callback_data="t:gawd"),
         B("🧱 ᴡᴀʟʟ", callback_data="t:glitch_wall")],
        [B("🔀 ᴍᴏᴅᴇ", callback_data="t:mode"), B("📊 sᴛᴀᴛs", callback_data="t:stats"),
         B("🔥 ᴍɪx", callback_data="t:mix")],
    ])


async def handle_text_callback(update: Any, ctx: Any) -> None:
    q = getattr(update, "callback_query", None)
    if not q or not getattr(q, "data", ""): return
    uid = int(getattr(getattr(q, "from_user", None), "id", 0) or 0)
    if not is_auth(uid):
        try: await q.answer("Owner only", show_alert=True)
        except Exception: pass
        return
    act = q.data[2:]
    try: await q.answer()
    except Exception: pass
    if act == "mode":
        global TEXT_MODE
        TEXT_MODE = {"rotate": "random", "random": "mix", "mix": "rotate"}[TEXT_MODE]
        body = card("🔀 ᴛᴇxᴛ ᴍᴏᴅᴇ", [kv("ᴍᴏᴅᴇ", TEXT_MODE),
                                    note("rotate → random → mix → rotate")])
    elif act == "mix":
        picks = [text_pick(k, chat_id(update)) for k in
                 ("nc_glitch", "slides", "spam", "swipe", "reply", "baap")]
        body = card("🔥 ᴛᴇxᴛ ᴍɪx", [note(esc(x[:70])) for x in picks])
    elif act == "stats":
        body = card("📊 ᴛᴇxᴛ ʙᴀɴᴋ sᴛᴀᴛs", [
            kv("sᴇᴄᴛɪᴏɴs", len(TEXT_META)),
            kv("ᴛᴏᴛᴀʟ ᴛᴇxᴛs", sum(text_stats().values())),
            sep(), text_table()])
    elif act in TEXT_META:
        picks = [text_pick(act, chat_id(update)) for _ in range(4)]
        body = card(f"{TEXT_META[act][0]} · ᴛᴇxᴛ sᴀᴍᴘʟᴇ", [
            kv("sᴇᴄᴛɪᴏɴ", act), kv("ᴛᴇxᴛs", len(bank(act))), sep(),
            *[note(esc(x[:90])) for x in picks],
            note("Har pick pe nayi line — rotation me repeat nahi."),
        ])
    else:
        return
    try: await q.message.edit_text(body, parse_mode="HTML",
                                  reply_markup=text_panel_keyboard())
    except Exception: pass


