# ── swipe / targetslide / picraid / emojirain ENGINES (advanced, stoppable) ───
SWIPE_TASKS: dict[int, asyncio.Task] = {}
TSLIDE_TASKS: dict[int, asyncio.Task] = {}
PIC_TASKS: dict[int, asyncio.Task] = {}
EMOJI_TASKS: dict[int, asyncio.Task] = {}
TASK_MAPS.extend([("sᴡɪᴘᴇ", SWIPE_TASKS), ("ᴛᴀʀɢᴇᴛsʟɪᴅᴇ", TSLIDE_TASKS),
                  ("ᴘɪᴄʀᴀɪᴅ", PIC_TASKS), ("ᴇᴍᴏᴊɪʀᴀɪɴ", EMOJI_TASKS)])


def _engine_loop(mapping: dict[int, asyncio.Task], cid: int, section: str,
                 gap: float, mode: str) -> None:
    stop = asyncio.Event()
    async def _run() -> None:
        i = 0
        while not stop.is_set():
            line = text_pick(section, cid)
            for b in pool():
                if stop.is_set(): break
                try:
                    if mode == "title":
                        await b.set_chat_title(cid, gawd_wrap(line, i))
                    elif mode == "slide":
                        await b.send_message(cid, fit(f"{HEARTS[i % len(HEARTS)]} {line}"))
                    elif mode == "emoji":
                        await b.send_message(cid, fit(
                            f"{line[:70]} {random.choice(HEARTS) * (i % 4 + 1)}"))
                    else:
                        await b.send_message(cid, fit(line))
                    i += 1
                except RetryAfter as e:
                    await nc_wait(stop, min(float(getattr(e, "retry_after", 1) or 1), FUSION_FLOOD_CAP)
                                  if float(getattr(e, "retry_after", 1) or 1) > 25 else 0.004)
                except Exception:
                    pass
            await nc_wait(stop, LOOP_DELAY.get(cid, gap))
    _start_loop(mapping, cid, _run)


