async def cmd_bank(update: Any, ctx: Any) -> None:
    """~bank <section> [title|msg|slide|emoji] — koi bhi text bank live loop me."""
    a = arg(update).strip(); cid = chat_id(update)
    parts = a.split()
    if not parts or parts[0].lower() in ("off", "stop"):
        cancel(BANK_TASKS, cid)
        return await render(update, ctx, "🛑 ʙᴀɴᴋ ʙᴀɴᴅ", [kv("ɢᴄ", cid)])
    sec = parts[0].lower()
    if sec not in TEXT_META:
        return await render(update, ctx, "🔥 ʙᴀɴᴋ sᴇʟᴇᴄᴛᴏʀ", [
            row(f"{p('bank')} <section> <mode>", "live loop"),
            note("26 sections: " + ", ".join(sorted(TEXT_META)[:13])),
            note("mode: title / msg / slide / emoji"),
            sep(), text_table(),
        ], reply_markup=text_panel_keyboard())
    mode = parts[1].lower() if len(parts) > 1 else "msg"
    if mode not in ("title", "msg", "slide", "emoji"): mode = "msg"
    _engine_loop(BANK_TASKS, cid, sec, 0.4, mode)
    await render(update, ctx, f"{TEXT_META[sec][0]} · ʙᴀɴᴋ ʟɪᴠᴇ", [
        kv("sᴇᴄᴛɪᴏɴ", sec), kv("ᴛᴇxᴛs", len(bank(sec))), kv("ᴍᴏᴅᴇ", mode),
        kv("ʙᴏᴛs", len(pool())),
        note(esc(text_pick(sec, cid)[:85])),
        row(f"{p('bank')} off", "rok do"),
    ], reply_markup=text_panel_keyboard())


async def cmd_raid(update: Any, ctx: Any) -> None:
    await cmd_bank(_WithText(update, f"{prefix_text()}bank raid title"), ctx)


async def cmd_broadcast_bank(update: Any, ctx: Any) -> None:
    if not is_owner(uid_of(update)): return
    text = arg(update).strip() or text_pick("broadcast", chat_id(update))
    ok = 0
    for c in sorted(KNOWN_CHATS):
        for b in pool():
            try: await b.send_message(c, fit(text)); ok += 1; break
            except Exception: continue
    await render(update, ctx, "📢 ʙʀᴏᴀᴅᴄᴀsᴛ", [
        kv("ɢᴄs", len(KNOWN_CHATS)), kv("ᴏᴋ", ok),
        note(esc(text[:80])),
        note("Khaali chhodo to broadcast bank se nayi line."),
    ])


